(21, 'seo_description', 'seo', 'Meta Description', 'textarea', 'Discover Hudayriyat Island, a premier luxury waterfront community in Abu Dhabi offering exclusive villas, mansions, and world-class amenities. Enjoy serene beaches, cultural heritage, and modern living in a secure and vibrant environment. Invest in your dream home today.', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
