(36, 'investment_description', 'investment', 'Investment Description', 'textarea', 'Hudayriyat Island offers attractive real estate investment opportunities through its premium villa communities, waterfront lifestyle, and developments by Modon Properties. With growing interest in luxury coastal living in Abu Dhabi, the island presents opportunities for investors seeking long-term capital appreciation and potential rental income.', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(37, 'investment_highlights_heading', 'investment', 'Highlights Heading', 'text', 'Key Investment Highlights:', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(38, 'investment_highlights', 'investment', 'Investment Highlights (one per line)', 'list', 'Premium villa communities with exclusive residential options\nDeveloped by Modon Properties\nStrong appeal among luxury homebuyers and property investors\nCoastal location with access to beaches and recreational facilities\nPotential for long-term capital appreciation\nAttractive lifestyle destination for families and investors\nGrowing residential and leisure destination in Abu Dhabi', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
