(41, 'financing_description', 'investment', 'Financing Card Description', 'textarea', 'Buying an off-plan property or a ready-to-move-in home? Maximise your buying power with competitive mortgage options tailored to your needs.', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(42, 'financing_highlights', 'investment', 'Financing Highlights (one per line)', 'list', 'Secure a mortgage during construction to maximize leverage\nCombine developer payment plans with tailored bank financing\nGet pre-approved in as little as 3 days\nConventional and Sharia-compliant financing available\nNo hidden fees or added costs', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
