(24, 16, 'disclaimer_content', 'Disclaimer Content Blocks', 2, 1, '{\"items\":[{\"title\":\"General Information Only\",\"description\":\"The content on this website, including property descriptions, pricing, payment plans, and market commentary, is provided for general informational purposes only and does not constitute an investment recommendation.\"},{\"title\":\"No Guarantee of Returns, Yield or Appreciation\",\"description\":\"Any rental yield or capital appreciation figure referenced on this Site is an indicative estimate based on market observations and does not constitute a guarantee of future returns.\"},{\"title\":\"Not Financial, Legal, Tax or Immigration Advice\",\"description\":\"Nothing on this website constitutes financial, legal, tax, or immigration advice, including advice relating to UAE residency or Golden Visa eligibility. Independent advice should be sought.\"},{\"title\":\"Developer & Property Information\",\"description\":\"Prices, availability, floor plans, and specifications are derived from developer materials and subject to change without notice. Confirm latest details with authorized specialists.\"},{\"title\":\"Regulatory Status\",\"description\":\"This website is not a government portal and is not affiliated with any UAE government authority. Nothing on this site should be interpreted as official government communication.\"},{\"title\":\"Testimonials\",\"description\":\"Client testimonials reflect individual experiences at the time they were provided and do not guarantee similar results for others.\"},{\"title\":\"Third-Party Links\",\"description\":\"Links to third-party websites are provided for convenience only. We do not endorse and are not responsible for external content or practices.\"},{\"title\":\"Accuracy of Information\",\"description\":\"While reasonable care is taken to maintain accurate information, we make no warranty regarding completeness and accept no liability for any error or omission.\"}]}', '2026-10-21 08:57:23', '2026-10-28 02:05:37'),
