(33, 6, 'amenities', 'Amenities & Facilities', 4, 1, '{\"title\":\"Bashayer Residences Amenities\",\"subtitle\":\"Residents at Bashayer can enjoy a range of facilities created for relaxation, recreation, and everyday convenience. The community includes a waterfront promenade, private marina and piers, clubhouse, rooftop infinity pool, gym, wellness facilities, sports courts, children\'s play areas, parks, cycling and jogging paths, dining, and retail spaces.\",\"items\":[]}', '2026-10-21 09:13:13', '2026-10-29 04:19:47'),
