(54, 13, 'amenities', 'Amenities & Facilities', 4, 1, '{\"title\":\"Nawayef Park Views Amenities\",\"subtitle\":\"Ideally located on Hudayriyat Island, Nawayef Park Views offers seamless access to Abu Dhabi\\u2019s top landmarks and lifestyle attractions. Just minutes from the beach, Nawayef Souq, and lush parklands, residents also enjoy close proximity to iconic destinations like Emirates Palace and Louvre Abu Dhabi.\",\"items\":[]}', '2026-10-21 09:13:13', '2026-10-29 04:20:13'),
(55, 4, 'about', 'About Community', 3, 1, '{\"tag\":\"ABOUT COMMUNITY\",\"heading\":\"Coastal Luxury Living\",\"description\":\"A prestigious residential destination on Hudayriyat Island offering unparalleled coastal grandeur, active outdoor living, and bespoke modern architecture.\",\"image\":\"\\/images\\/wadeem-gardens\\/amenity-club.png\",\"title\":\"Wadeem Gardens by Modon\",\"video_url\":null,\"video_poster\":\"\\/images\\/wadeem-gardens\\/video-poster.png\"}', '2026-10-21 09:31:36', '2026-10-29 04:21:17'),
