(57, 4, 'location', 'Location & Connectivity', 9, 1, '{\"title\":\"Wadeem Gardens Location & Attractions\",\"subtitle\":\"Wadeem Gardens is located on Hudayriyat Island, Abu Dhabi, with restaurants, schools and healthcare facilities accessible from the island.\",\"image\":\"\\/images\\/20231014_191447.webp\",\"categories\":[{\"name\":\"Restaurants\",\"items\":[{\"name\":\"Marmoura Restaurant & Lounge\",\"time\":\"Approximately 4 mins\"},{\"name\":\"The Plage Restaurant\",\"time\":\"Approximately 4 mins\"},{\"name\":\"Rain Cafe Hudayriat\",\"time\":\"Approximately 5 mins\"},{\"name\":\"Souvlaki Nation\",\"time\":\"Approximately 6 mins\"},{\"name\":\"Nalu Restaurant & Lounge\",\"time\":\"Approximately 8 mins\"}]},{\"name\":\"Hospitals & Clinics\",\"items\":[{\"name\":\"Burjeel Medical Center\",\"time\":\"Approximately 15 mins\"},{\"name\":\"Cleveland Clinic Abu Dhabi\",\"time\":\"Approximately 20 mins\"}]},{\"name\":\"Schools\",\"items\":[{\"name\":\"Cranleigh Abu Dhabi\",\"time\":\"Approximately 20 mins\"},{\"name\":\"The British School Al Khubairat\",\"time\":\"Approximately 15 mins\"}]},{\"name\":\"Landmarks\",\"items\":[{\"name\":\"Abu Dhabi International Airport\",\"time\":\"Approximately 20 mins\"},{\"name\":\"Downtown Abu Dhabi\",\"time\":\"Approximately 15 mins\"}]}]}', '2026-10-21 09:31:36', '2026-10-29 04:21:17');
