(58, 4, 'payment_plan', 'Payment Plan', 7, 1, '{\"title\":\"Payment Plan\",\"description\":\"Flexible installment plan structured with milestone payments.\",\"plan_tabs\":null,\"download_text\":\"DOWNLOAD PAYMENT PLAN\",\"download_url\":\"#\",\"rows\":[{\"installment\":\"Down Payment\",\"percentage\":\"10%\",\"milestone\":\"On Booking\"},{\"installment\":\"1st Installment\",\"percentage\":\"5%\",\"milestone\":\"Construction Milestone\"},{\"installment\":\"2nd Installment\",\"percentage\":\"10%\",\"milestone\":\"Construction Milestone\"},{\"installment\":\"3rd Installment\",\"percentage\":\"5%\",\"milestone\":\"Construction Milestone\"},{\"installment\":\"4th Installment\",\"percentage\":\"10%\",\"milestone\":\"Construction Milestone\"},{\"installment\":\"5th Installment\",\"percentage\":\"5%\",\"milestone\":\"Construction Milestone\"},{\"installment\":\"6th Installment\",\"percentage\":\"10%\",\"milestone\":\"Construction Milestone\"},{\"installment\":\"7th Installment\",\"percentage\":\"5%\",\"milestone\":\"Construction Milestone\"},{\"installment\":\"Final Payment\",\"percentage\":\"40%\",\"milestone\":\"On Handover\"}]}', '2026-10-21 09:31:36', '2026-10-29 04:21:17'),
(59, 4, 'faq', 'Frequently Asked Questions', 10, 1, '{\"title\":\"Frequently Asked Questions\",\"items\":[{\"q\":\"What is Wadeem Gardens?\",\"a\":\"Wadeem Gardens is an upcoming villa community by Modon on Hudayriyat Island, Abu Dhabi, featuring three gated villa clusters.\"},{\"q\":\"What types of villas are available at Wadeem Gardens?\",\"a\":\"Wadeem Gardens offers 4-, 5- and 6-bedroom villas with Contemporary Arabic and Modernist fa\\u00e7ades.\"},{\"q\":\"What is the starting price of Wadeem Gardens?\",\"a\":\"Wadeem Gardens starts from AED 8,700,000 for a 4-bedroom villa.\"},{\"q\":\"What are the villa sizes and plot sizes at Wadeem Gardens?\",\"a\":\"Villa sizes range from 4,628 to 6,358 sq. ft., while plot sizes range from 5,727 to 7,750 sq. ft.\"},{\"q\":\"What payment plans are available at Wadeem Gardens?\",\"a\":\"Wadeem Gardens offers two payment options: a 45\\/55 plan without finance and a 25\\/75 plan with finance.\"},{\"q\":\"What is the difference between the two Wadeem Gardens payment plans?\",\"a\":\"The 45\\/55 plan is listed without finance, while the 25\\/75 plan is listed with finance and is subject to off-plan mortgage approval.\"},{\"q\":\"When is the handover of Wadeem Gardens?\",\"a\":\"Wadeem Gardens is scheduled for handover in Q2 2031 under the 25\\/75 payment plan.\"},{\"q\":\"Where is Wadeem Gardens located and what is nearby?\",\"a\":\"Wadeem Gardens is located on Hudayriyat Island, with Zayed International Airport approximately 15 minutes away, ADGM 20 minutes, Louvre Museum 23 minutes, and Disneyland 25 minutes.\"}],\"heading\":\"Frequently Asked Questions\",\"subtitle\":null}', '2026-10-21 09:31:36', '2026-10-29 04:21:17'),
