(107, 12, 'faq', 'Frequently Asked Questions', 10, 1, '{\"title\":\"Frequently Asked Questions\",\"items\":[{\"q\":\"What are nearby dining options around Wadeem Plots?\",\"a\":\"Salar Restaurant (approx 10 mins), The Phuket Kitchen (approx 16 mins), Sama AlMoheet Seafood & Grill Restaurant (approx 11 mins), Sunset Life Restaurant and Cafe (approx 19 mins), and Al Shader Restaurant and Grill (approx 14 mins).\"},{\"q\":\"What shopping destinations are close to Wadeem Plots?\",\"a\":\"Mushrif Mall (approx 10 mins), Abu Dhabi Mall (approx 21 mins), The Galleria Mall (approx 21 mins), and Reem Mall (approx 23 mins).\"},{\"q\":\"What hotels & resorts are located near Wadeem Plots?\",\"a\":\"Radisson Blu Hotel & Resort (approx 21 mins), Four Seasons Hotel (approx 23 mins), Rosewood Hotel (approx 21 mins), The St. Regis Abu Dhabi (approx 18 mins), and Emirates Palace Mandarin Oriental (approx 16 mins).\"}],\"heading\":\"Frequently Asked Questions\",\"subtitle\":\"Key inquiries and essential information regarding ownership at Wadeem Plots\"}', '2026-10-21 09:31:36', '2026-10-29 04:20:23'),
