(113, 13, 'faq', 'Frequently Asked Questions', 11, 1, '{\"title\":\"FAQs\",\"items\":[{\"q\":\"Where is Nawayef Park Views located?\",\"a\":\"Nawayef Park Views is situated in the heart of Hudayriyat Island, Abu Dhabi, resting between the scenic Nawayef hills.\"},{\"q\":\"Who is the developer?\",\"a\":\"Developed by Modon Properties, a renowned Abu Dhabi-based developer known for crafting premium, sustainable communities.\"},{\"q\":\"What types of residences are available?\",\"a\":\"The community offers freehold apartments with 1 to 4 bedrooms, featuring private balconies or terraces. Larger units, ranging from 2 to 4 bedrooms, may include staff quarters and dedicated home office space.\"},{\"q\":\"What is the size range of the residences?\",\"a\":\"Residential units span from approximately 1,044 sq ft up to 5,328 sq ft.\"},{\"q\":\"When is the expected completion\\/ handover?\",\"a\":\"The project is scheduled for completion in Q1 2028.\"},{\"q\":\"What payment plan options are available?\",\"a\":\"A flexible 60\\/40 payment plan, requiring a 10% booking fee, followed by structured installments during construction, with the final 40% due at handover.\"},{\"q\":\"What amenities are included onsite?\",\"a\":\"Residents enjoy a wellness-focused lifestyle featuring a fully equipped gym, yoga zone, co-working space, barbecue and shaded green areas, clubhouse, children\\u2019s splash pool and play area, plus concierge, catering, and laundry services.\"},{\"q\":\"Who can buy and what are the investment benefits?\",\"a\":\"Available as freehold for all nationalities, the apartments are ideal for both residents and investors.\"}],\"heading\":\"FAQs\",\"subtitle\":\"\"}', '2026-10-21 09:31:37', '2026-10-29 04:20:13'),
(114, 13, 'contact', 'Contact & Booking CTA', 12, 1, '{\"form_small\":\"REQUEST\",\"form_large\":\"A CALL BACK\",\"submit_button\":\"REQUEST NOW\",\"terms_note\":\"By submitting, you agree to our Terms & Privacy Policy.\",\"bg_image\":\"\\/images\\/form image.jpg\",\"pretitle\":\"LET\'S CONNECT\",\"heading\":\"Invest in Your Future\",\"subtitle\":null}', '2026-10-21 09:31:37', '2026-10-29 04:20:13'),
