(472, 64, 'about', 'About lahore', 4, 1, '{\"title\":\"About the Community\",\"description\":\"A meticulously planned coastal sanctuary seamlessly integrating contemporary luxury living with untouched nature. Spanning scenic waterfronts, lush mangroves, and cycling corridors, the master community offers an unmatched urban lifestyle for residents and high-yield potential for global real estate investors.\",\"video_poster\":\"\\/images\\/cities\\/1793099946_about_image-hero.jpg\",\"video_src\":\"\\/images\\/nawayef-park-views\\/asset_15.mp4\",\"heading\":\"About the Community\",\"video_url\":\"https:\\/\\/stream.mux.com\\/A3200aZtT5Wq7VlYwQv3wP9W2hX8.m3u8\",\"poster_image\":\"\\/images\\/cities\\/1793099946_about_image-hero.jpg\"}', '2026-10-27 06:14:02', '2026-10-27 06:19:06'),
(473, 64, 'faq', 'Frequently Asked Questions', 5, 1, '{\"title\":\"Frequently Asked Questions\",\"description\":\"<p>Key information and helpful answers regarding lahore and property purchases on Hudayriyat Island.<\\/p>\",\"items\":[{\"q\":\"Are properties in this city freehold for foreign and overseas investors?\",\"a\":\"Yes, designated luxury master developments offer 100% freehold ownership for local and international buyers with complete title deed registration.\"},{\"q\":\"What are the typical payment plans available?\",\"a\":\"Flexible installment plans are offered typically linked to construction milestones, with down payments starting from 5% to 10%.\"}],\"heading\":\"Frequently Asked Questions\",\"subtitle\":\"Find answers to common questions about properties, buying process, and payment plans.\"}', '2026-10-27 06:14:02', '2026-10-27 06:14:02'),
